"""Nebraska Revised Statutes: every chapter's statute list (browse-chapters.php), then the Legislature's own range view (display_html.php) 400 statutes a request — ~250 requests for the whole code instead of 50k pages; comma ids (2-10,100) included."""
import re
B = "https://nebraskalegislature.gov/laws/"
CHUNK = 400

def key(s):
    """The range view's own order: 2-1099 < 2-10,100 < 2-10,100.01 < 2-1101 (a comma id follows its prefix's 99)."""
    m = re.match(r"(\d+)(?:,(\d+))?(?:\.(\d+))?([A-Za-z]*)$", s.split("-", 1)[1])
    if not m:
        return (10 ** 9, 0, 0, s)
    a, b, c, d = m.groups()
    return (int(a) * 100 + 99 if b else int(a), int(b or 0), int(c or 0), d)

def read(url, got):
    kind, body = fetch(url)
    marks = list(re.finditer(r'<strong>\s*(\d+-[0-9A-Za-z,.]+?)\.\s', body))
    for n, m in enumerate(marks):
        sid = m.group(1)
        end = marks[n + 1].start() if n + 1 < len(marks) else body.find("</body>")
        chunk = body[m.start():end]
        for stop in ('<div class="source"', '<div class="statute_source"', '<h2>'):
            k = chunk.find(stop)
            if k > 0:
                chunk = chunk[:k]
        h_end = chunk.find("</strong>")
        heading = " ".join(block_text("<div class='h'>" + chunk[m.end() - m.start():h_end] + "</div>", cls="h").split())
        rest = block_text("<div class='b'>" + chunk[h_end + 9:] + "</div>", cls="b")
        if sid in got or not heading:
            continue
        got.add(sid)
        yield {"id": sid, "heading": heading, "text": heading + ("\n" + rest if rest else ""), "url": url + "#" + sid}

def sections():
    kind, idx = fetch(B + "browse-statutes.php")
    chapters = []
    for c in re.findall(r'browse-chapters\.php\?chapter=([0-9A-Za-z]+)"', idx):
        if c not in chapters:
            chapters.append(c)
    log("chapters: %d" % len(chapters))
    total = 0
    for ch in chapters:
        kind, page = fetch(B + "browse-chapters.php?chapter=" + ch)
        ids = []
        for s in re.findall(r'statutes\.php\?statute=([^"&]+)"', page):
            if s.split("-")[0] == ch and s not in ids:
                ids.append(s)
        ids.sort(key=key)
        got = set()
        for i in range(0, len(ids), CHUNK):
            part = ids[i:i + CHUNK]
            yield from read(B + "display_html.php?begin_section=%s&end_section=%s" % (part[0], part[-1]), got)
        for s in [s for s in ids if s not in got][:200]:          # out of the range order: one by one
            yield from read(B + "display_html.php?begin_section=%s&end_section=%s" % (s, s), got)
        miss = [s for s in ids if s not in got]
        total += len(got)
        log("chapter %s: %d of %d statutes%s" % (ch, len(got), len(ids), (" — missing " + ", ".join(miss[:5])) if miss else ""))
    log("whole code: %d statutes" % total)
